void sGUIExt::setupChatTell() {
    uGUIChat* t0 = mChat.mpGUIChat;
    if (t0 == nullptr) {
        return;
    }
    if (t0->isEnable()) {
        if (t0->isMenuUI()) {
            if (mChat.mpGUIChat != nullptr) {
                if (mChat.mpGUIChat->isEnable()) {
                    if (mChat.mpGUIChat->isMenuUISubMenu()) {
                        if (t0->isEnable()) {
                            if (sChat::getInstance()->getTellCharacterId() != 0) {
                                mChat.mpGUIChat->mIsReqTellState = true;
                                mChat.mChatArea = 6;
                                sChat::getInstance()->mChatArea = 6;
                            }
                        }
                    }
                }
            }
        } else {
            if (mChat.mpGUIChat != nullptr) {
                if (t0->isEnable()) {
                    if (sChat::getInstance()->getTellCharacterId() != 0) {
                        mChat.mpGUIChat->mIsReqTellState = true;
                        mChat.mChatArea = 6;
                        sChat::getInstance()->mChatArea = 6;
                    }
                }
            }
        }
    } else {
        if (t0->isEnable()) {
            if (sChat::getInstance()->getTellCharacterId() != 0) {
                mChat.mpGUIChat->mIsReqTellState = true;
                mChat.mChatArea = 6;
                sChat::getInstance()->mChatArea = 6;
            }
        }
    }
}

