s32 sGUIExt::cDialog::getDialogPos() {
    if (mpGUISystemMsg != nullptr) {
        if (mpGUISystemMsg->mResult == uGUIBase::RESULT_EXIT) {
            s32 pos = mpGUISystemMsg->getChoicePos(-1);
            if (mpGUISystemMsg != nullptr) {
                mpGUISystemMsg->kill();
                mpGUISystemMsg = nullptr;
            }
            return pos;
        }
    }
    return -1;
}

